// Not generated by ent.

package ent

import "log/slog"

// LogValue implements [slog.LogValuer], so logging a user (e.g. the
// authenticated user in request logs) only includes identifiers, and not
// personal or moderation details like the email address or ban reason.
func (u *User) LogValue() slog.Value {
	if u == nil {
		return slog.Value{}
	}
	return slog.GroupValue(
		slog.Int("id", u.ID),
		slog.String("user_id", u.UserID),
		slog.String("username", u.Username),
		slog.Bool("admin", u.Admin),
	)
}
